// Auto-generated scoped styles for the Archive Commerce Page template (format-archive port).
// Every rule is scoped under .archive-commerce-page so the injected <style> never leaks globals.
export function getArchiveCommercePageStyles(assetBase: string) {
  return (
    ARCHIVE_COMMERCE_PAGE_STYLES.replaceAll("__ASSET_BASE__", assetBase) +
    STRUCTURAL_STYLES
  );
}

